function solve(input) {
  const cache = new Map();
  const results = [];

  for (const op of input) {
    if (op.op === "put") {
      if (op.ttl <= 0) {
        cache.delete(op.key);
      } else {
        cache.set(op.key, {
          value: op.value,
          expires: op.t + op.ttl
        });
      }
    } else if (op.op === "get") {
      const entry = cache.get(op.key);

      if (!entry || entry.expires <= op.t) {
        cache.delete(op.key);
        results.push(null);
      } else {
        results.push(entry.value);
      }
    } else if (op.op === "delete") {
      cache.delete(op.key);
    }
  }

  return results;
}
